  "times.py": "import datetime as _datetime

def instant(value):
    if isinstance(value, _datetime.datetime):
        dt = value
    elif isinstance(value, str):
        try:
            dt = _datetime.datetime.fromisoformat(value)
        except ValueError:
            raise ValueError('invalid ISO8601 string') from None
    else:
        raise ValueError('value must be a datetime or ISO8601 string')
    if dt.utcoffset() is None:
        raise ValueError('datetime must be timezone-aware')
    return dt.astimezone(_datetime.timezone.utc)",
  "quotes.py": "import math
import times

def probability(value):
    if isinstance(value, bool):
        raise ValueError('boolean odds are invalid')
    if isinstance(value, (int, float, str)):
        try:
            f = float(value)
        except (ValueError, OverflowError):
            raise ValueError('odds not representable as float') from None
    else:
        raise ValueError('unsupported odds type')
    if not math.isfinite(f):
        raise ValueError('odds must be finite')
    if abs(f) < 100.0:
        raise ValueError('odds magnitude must be at least 100')
    if f > 0:
        return 100.0 / (f + 100.0)
    else:
        return (-f) / ((-f) + 100.0)

def select(rows, event, asof):
    best = {}
    for row in rows:
        if not isinstance(row, dict):
            continue
        try:
            id_ = row['id']
            book = row['book']
            row_event = row['event']
            observed_at = times.instant(row['observed_at'])
            expires_at = times.instant(row['expires_at'])
            last_update = times.instant(row['last_update'])
            prob = probability(row['odds'])
        except (KeyError, ValueError, TypeError):
            continue
        if not (isinstance(id_, str) and len(id_) > 0 and
                isinstance(book, str) and len(book) > 0 and
                isinstance(row_event, str) and len(row_event) > 0):
            continue
        if row_event != event:
            continue
        if not (observed_at <= asof and asof < expires_at and last_update <= observed_at):
            continue
        current = best.get(book)
        if current is None:
            best[book] = (observed_at, id_, row, prob)
        else:
            current_obs, current_id, current_row, current_prob = current
            if observed_at > current_obs:
                best[book] = (observed_at, id_, row, prob)
            elif observed_at == current_obs:
                if id_ < current_id:
                    best[book] = (observed_at, id_, row, prob)
    return {book: {'row': row, 'probability': prob}
            for book, (obs, id_, row, prob) in best.items()}",
  "runs.py": "import times

def reconcile(rows, asof):
    dedup = {}
    for row in rows:
        if not isinstance(row, dict):
            continue
        try:
            run_id = row['run_id']
            job = row['job']
            attempt = row['attempt']
            observed_at = times.instant(row['observed_at'])
            status = row['status']
            downloaded_rows = row['downloaded_rows']
        except (KeyError, ValueError, TypeError):
            continue
        if not (isinstance(run_id, str) and len(run_id) > 0 and
                isinstance(job, str) and len(job) > 0):
            continue
        if not (isinstance(attempt, int) and not isinstance(attempt, bool) and attempt > 0):
            continue
        if not (isinstance(status, str) and status in ('ok', 'partial', 'failed', 'pending')):
            continue
        if not (isinstance(downloaded_rows, int) and not isinstance(downloaded_rows, bool) and downloaded_rows >= 0):
            continue
        if status in ('failed', 'pending') and downloaded_rows != 0:
            continue
        if observed_at > asof:
            continue
        current = dedup.get(run_id)
        if current is None:
            dedup[run_id] = (observed_at, row)
        else:
            current_obs, current_row = current
            if observed_at > current_obs:
                dedup[run_id] = (observed_at, row)
    best = {}
    for run_id, (observed_at, row) in dedup.items():
        job = row['job']
        attempt = row['attempt']
        current = best.get(job)
        if current is None:
            best[job] = (attempt, observed_at, run_id, row)
        else:
            current_attempt, current_obs, current_run_id, current_row = current
            if attempt > current_attempt:
                best[job] = (attempt, observed_at, run_id, row)
            elif attempt == current_attempt:
                if observed_at > current_obs:
                    best[job] = (attempt, observed_at, run_id, row)
                elif observed_at == current_obs:
                    if run_id < current_run_id:
                        best[job] = (attempt, observed_at, run_id, row)
    return {job: row for job, (attempt, observed_at, run_id, row) in best.items()}",
  "pipeline.py": "import times
import quotes
import runs

def snapshot(quote_rows, run_rows, event, asof):
    asof_dt = times.instant(asof)
    if not isinstance(event, str) or len(event) == 0:
        raise ValueError('event must be a nonempty string')
    q = quotes.select(quote_rows, event, asof_dt)
    r = runs.reconcile(run_rows, asof_dt)
    successful_rows = 0
    failures = []
    partial_jobs = []
    unknown_jobs = []
    for job, row in r.items():
        status = row['status']
        downloaded = row['downloaded_rows']
        if status == 'ok' or status == 'partial':
            successful_rows += downloaded
        if status == 'failed':
            failures.append(job)
        elif status == 'partial':
            partial_jobs.append(job)
        elif status == 'pending':
            unknown_jobs.append(job)
    return {
        'quotes': q,
        'runs': r,
        'successful_rows': successful_rows,
        'failures': sorted(failures),
        'partial_jobs': sorted(partial_jobs),
        'unknown_jobs': sorted(unknown_jobs),
    }"
}
